"""Writes every generated file: memory images, the MCU weight header,
the program listing, and the test vectors described in fpga/sim/README.md.
"""

from pathlib import Path

import numpy as np

import luts
from assembler import assemble, write_listing
from config import MCU_SRC_DIR, MEM_DIR, VECTOR_DIR
from isa import A_K0, F_ALT, encode
from isa_sim import Machine, word_tokens
from quantize import PRE_SHIFT, QModel, load_params, quantize
from ref_int import rmsnorm, rq, softmax

SPRAM_MEM_WORDS = 0x3480
MCU_WORDS = A_K0
KV_WORDS = SPRAM_MEM_WORDS - A_K0
PREFIXES = ["", "a", "em", "ja", "kri", "mar", "zoe"]
N_UNIT = 64

# ------------------------------------------------------------------------------
# Formatting
# ------------------------------------------------------------------------------


def hexs(value: int, digits: int) -> str:
    """Two's-complement hex string of a fixed width.

    Args:
        value: Signed or unsigned integer.
        digits: Hex digits.

    Returns:
        Zero-padded lowercase hex.
    """
    return f"{int(value) & ((1 << 4 * digits) - 1):0{digits}x}"


def word_hex(lanes: np.ndarray) -> str:
    """One 64-bit SPRAM word as 16 hex digits, lane l at bits 8l+7:8l.

    Args:
        lanes: Eight signed bytes, lane 0 first.

    Returns:
        Hex string, lane 7 first.
    """
    return "".join(hexs(b, 2) for b in reversed(lanes))


def write_lines(path: Path, lines: list[str]) -> None:
    """Write lines to a file, creating its directory.

    Args:
        path: Output file.
        lines: Lines without newlines.
    """
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(f"{line}\n" for line in lines))


def c_array(name: str, values: list[int], per_line: int = 16) -> str:
    """Format bytes as a C uint8_t array definition.

    Args:
        name: Array name.
        values: Byte values; only the low 8 bits are kept.
        per_line: Values per source line.

    Returns:
        C source text.
    """
    rows = [", ".join(f"0x{v & 0xff:02x}" for v in values[i:i + per_line])
            for i in range(0, len(values), per_line)]
    return f"const uint8_t {name}[{len(values)}] = {{\n    " + \
        ",\n    ".join(rows) + "\n};\n"


# ------------------------------------------------------------------------------
# Memory images and MCU header
# ------------------------------------------------------------------------------


def export_memories(qm: QModel, prog: list[int], spram: np.ndarray) -> None:
    """Write spram.mem, prog.mem, the lookup tables, program.lst and
    mcu/src/model_weights.h.

    Args:
        qm: Quantized model.
        prog: Instruction words.
        spram: SPRAM image.
    """
    write_lines(MEM_DIR / "spram.mem",
                [word_hex(w) for w in spram[:SPRAM_MEM_WORDS]])
    write_lines(MEM_DIR / "prog.mem", [hexs(w, 12) for w in prog])
    luts.main()
    write_listing(prog)

    spram_bytes = spram[:MCU_WORDS].reshape(-1).tolist()
    prog_bytes = [w >> (8 * k) for w in prog for k in range(5, -1, -1)]
    header = ("// model_weights.h\n"
              "// Generated by model/export.py; do not edit\n\n"
              "#ifndef MODEL_WEIGHTS_H\n#define MODEL_WEIGHTS_H\n\n"
              "#include <stdint.h>\n\n"
              f"#define MODEL_NWORDS {MCU_WORDS}\n"
              f"#define MODEL_NINSTR {len(prog)}\n"
              f"#define MODEL_LOGIT_FRAC {qm['f']['logit']}\n\n"
              + c_array("model_spram", spram_bytes) + "\n"
              + c_array("model_prog", prog_bytes) +
              "\n#endif // MODEL_WEIGHTS_H\n")
    (MCU_SRC_DIR / "model_weights.h").write_text(header)


# ------------------------------------------------------------------------------
# Whole-program test vectors
# ------------------------------------------------------------------------------


def export_prefixes(qm: QModel, prog: list[int]) -> None:
    """For each test prefix and position: the register file after every
    instruction, the KV region after the letter, and the scores.

    Args:
        qm: Quantized model.
        prog: Instruction words.
    """
    for prefix in PREFIXES:
        machine = Machine(qm, prog)
        out = VECTOR_DIR / f"prefix_{prefix or 'empty'}"
        for pos, tok in enumerate(word_tokens(prefix)):
            trace: list[np.ndarray] = []
            scores = machine.run(tok, pos, trace)
            write_lines(out / f"pos{pos}_vreg.mem",
                        [hexs(v, 4) for vr in trace for v in vr])
            write_lines(out / f"pos{pos}_kv.mem",
                        [word_hex(w)
                         for w in machine.spram[A_K0:A_K0 + KV_WORDS]])
            write_lines(out / f"pos{pos}_scores.mem",
                        [hexs(v, 4) for v in scores[:27]])


# ------------------------------------------------------------------------------
# Unit test vectors
# ------------------------------------------------------------------------------


def edge_int16(rng: np.random.Generator, n: int) -> np.ndarray:
    """Random int16 values whose first entries are the edge cases.

    Args:
        rng: Random generator.
        n: Number of values, at least 7.

    Returns:
        Values.
    """
    edges = np.array([-32768, -32767, -1, 0, 1, 32766, 32767])
    values = rng.integers(-32768, 32768, n)
    values[:len(edges)] = edges
    return values


def unit_requant(rng: np.random.Generator) -> list[str]:
    """Requantize cases, one line each: acc, shift, sat8, y.

    Args:
        rng: Random generator.

    Returns:
        Lines.
    """
    lines = []
    for _ in range(N_UNIT * 16):
        acc = int(rng.integers(-(1 << 31), 1 << 31) >> rng.integers(0, 31))
        shift, sat8 = int(rng.integers(0, 16)), int(rng.integers(0, 2))
        y = rq(np.int64(acc), shift, bool(sat8))
        lines.append(hexs(acc, 8) + hexs(shift, 1) + hexs(sat8, 1)
                     + hexs(y, 4))
    return lines


def unit_rmsnorm(rng: np.random.Generator) -> list[str]:
    """RMSNORM cases: header {a, o}, 64 inputs, 64 outputs.

    Args:
        rng: Random generator.

    Returns:
        Lines.
    """
    lines = []
    for i in range(N_UNIT):
        x = edge_int16(rng, 64) >> rng.integers(0, 15) if i else \
            np.zeros(64, dtype=np.int64)
        o = int(rng.integers(0, 4))
        lines += [hexs(PRE_SHIFT << 4 | o, 4)]
        lines += [hexs(v, 4) for v in x]
        lines += [hexs(v, 4) for v in rmsnorm(x, PRE_SHIFT, o)]
    return lines


def unit_softmax(rng: np.random.Generator) -> list[str]:
    """SOFTMAX cases: header {pos, k}, 16 scores, 16 outputs.

    Args:
        rng: Random generator.

    Returns:
        Lines.
    """
    lines = []
    for _ in range(N_UNIT):
        s = edge_int16(rng, 16) >> rng.integers(0, 15)
        pos, k = int(rng.integers(0, 16)), int(rng.integers(0, 16))
        lines += [hexs(pos << 8 | k, 4)]
        lines += [hexs(v, 4) for v in s]
        lines += [hexs(v, 4) for v in softmax(s, pos, k)]
    return lines


def unit_op(qm: QModel, prog: list[int], rng: np.random.Generator, op: str,
            **fields: int) -> tuple[np.ndarray, np.ndarray, Machine, int, int]:
    """Run one instruction on a machine with random register and SPRAM contents.

    Args:
        qm: Quantized model.
        prog: Program, used only to construct the machine.
        rng: Random generator.
        op: Opcode name.
        fields: Decoded instruction fields.

    Returns:
        Registers and SPRAM before, the machine after, letter, pos.
    """
    machine = Machine(qm, prog)
    machine.vr[:] = edge_int16(rng, 1024) >> rng.integers(0, 15)
    machine.spram[:] = rng.integers(-128, 128, machine.spram.shape)
    machine.spram[A_K0:A_K0 + KV_WORDS] = 0
    machine.prog = [dict(fields, op=op)]
    letter, pos = int(rng.integers(0, 27)), int(rng.integers(0, 16))
    before_vr, before_sp = machine.vr.copy(), machine.spram.copy()
    machine.run(letter, pos)
    return before_vr, before_sp, machine, letter, pos


def unit_machine_ops(qm: QModel, prog: list[int],
                     rng: np.random.Generator) -> dict[str, list[str]]:
    """MATVEC, EMBED, KVSTORE, VADD and VRELU cases.

    Args:
        qm: Quantized model.
        prog: Program, used only to construct machines.
        rng: Random generator.

    Returns:
        Lines keyed by file name.
    """
    files = {}
    lines = []
    for _ in range(N_UNIT):
        shift = int(rng.integers(0, 16))
        sat8, alt = int(rng.integers(0, 2)), int(rng.integers(0, 2))
        fields = dict(src=16, dst=48, base=0x0100, rows=16, cols=16,
                      shift=shift, flags=sat8 | alt << F_ALT)
        vr, sp, m, _, _ = unit_op(qm, prog, rng, "MATVEC", **fields)
        out = m.score[:16] if alt else m.vr[384:400]
        lines += [hexs(encode("MATVEC", **fields), 12)]
        lines += [hexs(v, 4) for v in vr[128:144]]
        lines += [word_hex(w) for w in sp[0x100:0x120]]
        lines += [hexs(v, 4) for v in out]
    files["matvec.mem"] = lines

    lines = []
    for _ in range(N_UNIT):
        shift = int(rng.integers(0, 8))
        _, sp, m, letter, pos = unit_op(qm, prog, rng, "EMBED", src=0, dst=0,
                                        base=0, rows=8, cols=64, shift=shift,
                                        flags=0)
        lines += [hexs(letter << 8 | pos << 4 | shift, 4)]
        lines += [word_hex(w) for w in sp[8 * letter:8 * letter + 8]]
        lines += [word_hex(w) for w in sp[256 + 8 * pos:256 + 8 * pos + 8]]
        lines += [hexs(v, 4) for v in m.vr[:64]]
    files["embed.mem"] = lines

    lines = []
    for _ in range(N_UNIT):
        alt = int(rng.integers(0, 2))
        vr, _, m, _, pos = unit_op(qm, prog, rng, "KVSTORE", src=24, dst=0,
                                   base=A_K0, rows=8, cols=64, shift=0,
                                   flags=alt << F_ALT)
        lines += [hexs(pos << 4 | alt, 4)]
        lines += [hexs(v, 4) for v in vr[192:256]]
        lines += [word_hex(w) for w in m.spram[A_K0:A_K0 + 128]]
    files["kvstore.mem"] = lines

    for op in ("VADD", "VRELU"):
        lines = []
        for _ in range(N_UNIT):
            vr, _, m, _, _ = unit_op(qm, prog, rng, op, src=56, dst=0,
                                     base=0, rows=8, cols=64, shift=0,
                                     flags=0)
            if op == "VADD":
                lines += [hexs(v, 4) for v in vr[:64]]
            lines += [hexs(v, 4) for v in vr[448:512]]
            lines += [hexs(v, 4) for v in m.vr[:64]]
        files[f"{op.lower()}.mem"] = lines
    return files


def export_units(qm: QModel, prog: list[int], seed: int = 155) -> None:
    """Write all unit test vector files to fpga/sim/vectors/unit.

    Args:
        qm: Quantized model.
        prog: Instruction words.
        seed: Random seed.
    """
    rng = np.random.default_rng(seed)
    files = {"requant.mem": unit_requant(rng),
             "rmsnorm.mem": unit_rmsnorm(rng),
             "softmax.mem": unit_softmax(rng)}
    files.update(unit_machine_ops(qm, prog, rng))
    for name, lines in files.items():
        write_lines(VECTOR_DIR / "unit" / name, lines)


def main() -> None:
    """Quantize the trained model and write every generated file."""
    qm = quantize(load_params())
    prog = assemble(qm)
    spram = Machine(qm, prog).spram
    export_memories(qm, prog, spram)
    export_prefixes(qm, prog)
    export_units(qm, prog)


if __name__ == "__main__":
    main()
